minted = {}

def committed_receipt(run, objects, blobs, execution_id):
    """A receipt minted by the reference commit path, identity-model.v3 EvidenceStore.prepare then commit, whose
    trusted replay adapter re-derives the proof with evaluator_replay_model.v3.derive over the admitted Run."""
    key = (id(run), execution_id)
    if key not in minted:
        seal = objects[run["evaluationSealId"]][1]
        _, owner = M.open_run_closure(run, objects, blobs)

        def replay(plan, objs, bl, refs):
            return R.derive(run["planId"], seal["executionPlanId"], seal["evaluatorClosure"], refs, objs, bl, owner)["proof"]

        store = M.EvidenceStore()
        store.prepare(run, objects, blobs, execution_id, replay)
        if store.commit(execution_id) != "committed":
            raise AssertionError("reference commit path did not commit")
        minted[key] = store.receipts[0]
    return dict(minted[key])

